//! Object storage: S3-compatible (MinIO) in production, local filesystem in development.

use std::path::PathBuf;

use anyhow::Context;
use bytes::Bytes;
use s3::creds::Credentials;
use s3::{Bucket, Region};

use crate::config::Config;

pub enum Storage {
    Local(PathBuf),
    S3(Box<Bucket>),
}

/// Keys are generated by the server, but validate anyway to rule out path traversal.
fn valid_key(key: &str) -> bool {
    !key.is_empty()
        && key.len() <= 200
        && !key.contains("..")
        && !key.starts_with('/')
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'/' | b'_' | b'-' | b'.'))
}

impl Storage {
    pub async fn from_config(cfg: &Config) -> anyhow::Result<Self> {
        match &cfg.s3 {
            Some(s3) => {
                let region = Region::Custom {
                    region: s3.region.clone(),
                    endpoint: s3.endpoint.clone(),
                };
                let creds =
                    Credentials::new(Some(&s3.access_key), Some(&s3.secret_key), None, None, None)
                        .context("invalid S3 credentials")?;
                let bucket = Bucket::new(&s3.bucket, region, creds)
                    .context("invalid S3 bucket")?
                    .with_path_style();
                tracing::info!(endpoint = %s3.endpoint, bucket = %s3.bucket, "using S3 storage");
                Ok(Storage::S3(bucket))
            }
            None => {
                let dir = PathBuf::from(&cfg.upload_dir);
                tokio::fs::create_dir_all(&dir)
                    .await
                    .with_context(|| format!("create {}", dir.display()))?;
                tracing::info!(dir = %dir.display(), "using local storage");
                Ok(Storage::Local(dir))
            }
        }
    }

    pub async fn put(&self, key: &str, data: Bytes, content_type: &str) -> anyhow::Result<()> {
        anyhow::ensure!(valid_key(key), "invalid storage key");
        match self {
            Storage::Local(dir) => {
                let path = dir.join(key);
                if let Some(parent) = path.parent() {
                    tokio::fs::create_dir_all(parent).await?;
                }
                tokio::fs::write(path, &data).await?;
            }
            Storage::S3(bucket) => {
                let res = bucket
                    .put_object_with_content_type(key, &data, content_type)
                    .await?;
                anyhow::ensure!(
                    res.status_code() < 300,
                    "S3 put failed with status {}",
                    res.status_code()
                );
            }
        }
        Ok(())
    }

    pub async fn get(&self, key: &str) -> anyhow::Result<Option<Bytes>> {
        if !valid_key(key) {
            return Ok(None);
        }
        match self {
            Storage::Local(dir) => match tokio::fs::read(dir.join(key)).await {
                Ok(data) => Ok(Some(Bytes::from(data))),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(e) => Err(e.into()),
            },
            Storage::S3(bucket) => match bucket.get_object(key).await {
                Ok(res) if res.status_code() == 200 => Ok(Some(res.bytes().clone())),
                Ok(res) if res.status_code() == 404 => Ok(None),
                Ok(res) => anyhow::bail!("S3 get failed with status {}", res.status_code()),
                Err(s3::error::S3Error::HttpFailWithBody(404, _)) => Ok(None),
                Err(e) => Err(e.into()),
            },
        }
    }
}

/// Supported image types, detected by magic bytes.
pub fn sniff_image(data: &[u8]) -> Option<&'static str> {
    match data {
        [0x89, b'P', b'N', b'G', ..] => Some("image/png"),
        [0xFF, 0xD8, 0xFF, ..] => Some("image/jpeg"),
        [b'G', b'I', b'F', b'8', ..] => Some("image/gif"),
        [
            b'R',
            b'I',
            b'F',
            b'F',
            _,
            _,
            _,
            _,
            b'W',
            b'E',
            b'B',
            b'P',
            ..,
        ] => Some("image/webp"),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(valid_key("avatars/123/abcdef"));
        assert!(!valid_key("../etc/passwd"));
        assert!(!valid_key("/abs"));
        assert!(!valid_key("a b"));
        assert!(!valid_key(""));
    }

    #[test]
    fn sniffing() {
        assert_eq!(sniff_image(b"\x89PNG\r\n\x1a\n"), Some("image/png"));
        assert_eq!(sniff_image(b"GIF89a"), Some("image/gif"));
        assert_eq!(sniff_image(b"RIFF\0\0\0\0WEBPVP8 "), Some("image/webp"));
        assert_eq!(sniff_image(b"<svg"), None);
    }
}
